// veld — generated by veld, rewritten when veld changes. Never edit by hand.
//
// (That line is for the copy in Veld's folder. This file is the template, in
// crates/veld-core/src/agent/claude-mod/, whose placeholders Veld fills. Nothing
// in CI typechecks it; `claude plugin validate` on the written folder, which
// `veld self doctor` runs, is the check.)
//
// Veld's Claude Code mod: tells Veld's window when this session is working, waiting
// for you or finished, and tells the agent how to put a file in front of you. Loaded
// only through CLAUDE_CODE_PLUGIN_DIRS in a Veld terminal, and inert anywhere it finds
// no Veld session.
import type { EngineInterface, Register } from 'claude-code'

const DAEMON = __VELD_DAEMON__
const CONTEXT = __VELD_CONTEXT__
const NAMING = __VELD_NAMING__
const TIMEOUT_MS = __VELD_TIMEOUT_MS__

// Read once per load: `session.start` runs before any other event, and a reload runs
// it again.
let session = ''
let hooks = false
let context = false
// The context rides the first prompt of each conversation: a session's first, and the
// first after a /clear, which ends the conversation without a new `session.start`.
let contextPending = false
// A tool-approval dialog or a question is on screen. Cleared by the next tool call
// that starts, the last one running returning, an MCP server's question being
// answered, the turn ending, or a new one starting.
let blocked = false
// The one on screen is a question the mod sees answered (`AskUserQuestion`,
// `ExitPlanMode`, an MCP server's question), reported held: only that answer, the turn
// ending or a new one starting clears it, never another call, a subagent's included,
// starting or returning beside it.
let held = false
// Tool calls under way, subagents' included: one returning while another still waits
// on a dialog does not answer that dialog.
let running = 0
// Whether Claude's classic hook events reach this mod, which they do only where no
// organization guard sits in front of them. Where they do, `permission_prompt` says an
// approval dialog is on screen; where they do not, a `tool.check` ask is the only sign
// left, and it fires for every call the auto-mode classifier then approves unseen.
// Kept across sessions, and settled again by each turn that ends with or without its
// `classic.Stop`.
let classic = false
let stopSeen = false
const CLASSIC = 'classicEvents'
// A resumed conversation named its worktree the first time round; Veld nudges only a
// new one to name it. The first prompt and the first stop are each put to the daemon
// once, and it keeps the rest of the count. `launchedAt` is this process's start.
let launchedAt = 0
let namingPrompt = false
let namingStop = false
// Veld rewrites these files when it is upgraded, which reloads them in every running
// session and resets the variables above. The ones that are the session's own, not read
// from its environment, are kept where a reload does not reach; that they are kept at
// all is how a reloaded `session.start` knows the session had already started.
const KEPT = { plugin: 'veld', key: 'session' } as const

export const register: Register = (on) => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    session = (await $.env.get('VELD_PTY_SESSION')) ?? ''
    // A `-p` run draws nothing and has nobody to wait on: it inherits the variables
    // from a Veld terminal and must still report nothing.
    const interactive = (await $.session.surface()) !== null
    const mine = interactive && session !== '' && (await $.env.get('VELD_CLAUDE_INTEGRATION')) === 'mod'
    hooks = mine && !!(await $.env.get('VELD_AGENT_HOOKS'))
    context = mine && !!(await $.env.get('VELD_AGENT_CONTEXT'))
    classic = (await $.store.get(CLASSIC).catch(() => undefined)) === true
    // A reload mid-session: the session is wherever it was, and owes what it owed.
    const kept = await $.state.get(KEPT).then((read) => read.value, () => undefined)
    if (kept) {
      contextPending = kept.contextPending
      blocked = kept.blocked
      held = kept.held ?? false
      // Kept by a mod from before the naming nudge: nothing left to ask.
      launchedAt = kept.launchedAt ?? Number.POSITIVE_INFINITY
      namingPrompt = kept.namingPrompt ?? true
      namingStop = kept.namingStop ?? true
      return result
    }
    contextPending = context
    blocked = false
    held = false
    launchedAt = await $.clock.now()
    namingPrompt = false
    namingStop = false
    await keep($)
    if (hooks) await report($, 'ready')
    return result
  })

  // A compacted conversation keeps a summary of the prompt that carried the context,
  // not the context, so the next prompt carries it again.
  on('session.compact', async ($, e, next) => {
    const result = await next(e)
    // A compaction another hook skipped left the conversation, context and all, as it was.
    if (!('skip' in result) && e.agentId === undefined) await setPending($, context)
    return result
  }).catch(passThrough)

  on('prompt.submit', async ($, e, next) => {
    if (!contextPending) return next(e)
    await setPending($, false)
    // Where outfit has profiles to offer, Veld has a note about them for this
    // session's first prompt — taken once, so a later conversation does not get it.
    const outfit = await askContext($)
    const extra = outfit ? [CONTEXT, outfit] : [CONTEXT]
    return next({ ...e, context: [...(e.context ?? []), ...extra] })
  }).catch(passThrough)

  // Subagents raise no `turn.start`: this is always the session's own turn.
  on('turn.start', async ($, e, next) => {
    const result = await next(e)
    stopSeen = false
    await setBlocked($, false)
    if (hooks) await report($, 'working')
    // A first turn interrupted (Esc) gets no stop: this one is a later turn, which is
    // never nudged, so Veld is told to settle.
    if (hooks && context && namingPrompt && !namingStop) {
      namingStop = true
      await keep($)
      await askNaming($, { turn: 'prompt', fresh: false })
    }
    // The context on this first prompt was the reminder; this tells Veld the stop may
    // need refusing.
    if (hooks && context && !namingPrompt) {
      namingPrompt = true
      await keep($)
      // Asked here, not at `session.start`, because `/resume` inside a running session
      // starts no new one. A resumed conversation's figures count from its first
      // launch, so a start well before this process's is one that already had its
      // first turn. Unknown counts as resumed: a missed nudge costs less than one that
      // renames a worktree its agent already named.
      const resumed = await $.session
        .usage()
        .then((u) => u.startedAt < launchedAt - 60_000, () => true)
      await askNaming($, { turn: 'prompt', fresh: !resumed })
    }
    return result
  })

  // A first turn that ends with the worktree still unnamed is refused once. Classic,
  // like `classic.Notification` below, so it reaches a mod only where no organization
  // guard sits in front of it; where one does, the context alone asks.
  on('classic.Stop', async ($, e, next) => {
    const result = await next(e)
    stopSeen = true
    if (hooks) await setClassic($, true)
    if (!hooks || !context || !namingPrompt || namingStop) return result
    namingStop = true
    await keep($)
    const verdict = await askNaming($, { turn: 'stop', continued: e.stop_hook_active === true })
    if (verdict !== 'block') return result
    // The turn goes on to name the worktree; `turn.complete`'s report comes when it ends.
    await report($, 'working')
    return { ...result, block: NAMING }
  }).catch(passThrough)

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    // A subagent's run is not the session's turn, and not news for the person.
    if (!hooks || e.agentId !== undefined) return result
    await setBlocked($, false)
    if (e.reason === 'aborted') {
      await report($, 'settled')
    } else if (e.reason === 'error') {
      await report($, 'blocked')
    } else {
      // A turn that ended on an answer passed `classic.Stop`, which runs before the
      // turn completes, on its way out, if it reaches this mod at all.
      if (e.reason === 'answer') await setClassic($, stopSeen)
      // Background agents still running will wake the session again by themselves,
      // so the end of this turn is not the session finishing.
      const agents = await $.agent.list()
      const waiting = agents.some((a) => a.status === 'running' && a.teammateId === undefined)
      await report($, waiting ? 'delegated' : 'idle')
    }
    return result
  })

  // An ask is put to the mode's decider, which is the dialog or, in auto mode, a
  // classifier that shows nothing. So it stands in for `permission_prompt` only where
  // classic events do not reach this mod, and is not held: nothing says when it is
  // answered, and the person answering it is looking at the pane, which reads it.
  on('tool.check', async ($, e, next) => {
    const verdict = await next(e)
    if (hooks && !classic && !blocked && verdict.decision === 'ask') {
      await setBlocked($, true)
      await report($, 'blocked')
    }
    return verdict
  }).catch(passThrough)

  on('tool.call', async ($, e, next) => {
    if (!hooks) return next(e)
    if (e.tool === 'AskUserQuestion' || e.tool === 'ExitPlanMode') {
      await setBlocked($, true, true)
      await report($, 'blocked', true)
      const result = await next(e)
      await setBlocked($, false)
      await report($, 'working')
      return result
    }
    if (blocked && !held) {
      await setBlocked($, false)
      await report($, 'working')
    }
    // `next` holds the approval dialog as well as the run, so a dialog answered while
    // this call waited on it is over by the time it returns.
    running++
    try {
      return await next(e)
    } finally {
      running--
      if (blocked && !held && running === 0) {
        await setBlocked($, false)
        await report($, 'working')
      }
    }
  }).catch(passThrough)

  // Claude's own `Notification` hook event, for the dialogs the mod events do not show:
  // the approval dialog, an MCP server asking through Claude, and a subagent asking for
  // input. It reaches a
  // mod only where no organization guard sits in front of it, and where one does this
  // never runs. The approval dialog is a `Notification` too: `permission_prompt`, sent
  // only once a dialog is on screen, never for a call the auto-mode classifier decides.
  on('classic.Notification', async ($, e, next) => {
    const result = await next(e)
    if (!hooks) return result
    await setClassic($, true)
    switch (e.notification_type) {
      // Not held, for the reason `tool.check`'s stand-in is not. A question already on
      // screen is the one being asked, and keeps its hold.
      case 'permission_prompt':
        if (!blocked) {
          await setBlocked($, true)
          await report($, 'blocked')
        }
        break
      case 'elicitation_dialog':
      case 'elicitation_url_dialog':
        await setBlocked($, true, true)
        await report($, 'blocked', true)
        break
      case 'elicitation_response':
      case 'elicitation_complete':
        if (blocked) {
          await setBlocked($, false)
          await report($, 'working')
        }
        break
      // Answered in the subagent, which tells this session nothing when it is: held,
      // it would stay "waiting" until the session's own next state.
      case 'agent_needs_input':
        if (!held) {
          await setBlocked($, true)
          await report($, 'blocked')
        }
        break
    }
    return result
  }).catch(passThrough)

  on('session.end', async ($, e, next) => {
    const result = await next(e)
    if (e.reason === 'clear') {
      await setPending($, context)
      // A new conversation in this terminal: the name the last one chose is final
      // now. Its own turn kind, so the nudge for the new conversation is untouched.
      if (hooks && context) await askNaming($, { turn: 'clear' })
    } else if (hooks && e.reason !== 'resume') {
      await report($, 'done')
    }
    return result
  })
}

// What a hook that failed answers in its place: the event goes on as if this mod were
// not here. Nothing veld does is worth refusing a prompt or a tool call over.
const passThrough = (_$: unknown, e: any, next: (e: any) => any) => next(e)

async function keep($: EngineInterface): Promise<void> {
  try {
    await $.state.set(KEPT, { contextPending, blocked, held, launchedAt, namingPrompt, namingStop })
  } catch {}
}

async function setPending($: EngineInterface, value: boolean): Promise<void> {
  if (contextPending === value) return
  contextPending = value
  await keep($)
}

async function setClassic($: EngineInterface, value: boolean): Promise<void> {
  if (classic === value) return
  classic = value
  try {
    await $.store.set(CLASSIC, value)
  } catch {}
}

async function setBlocked($: EngineInterface, value: boolean, asked = false): Promise<void> {
  if (blocked === value && held === (value && asked)) return
  blocked = value
  held = value && asked
  await keep($)
}

// The report before this one, still being sent.
let sending: Promise<unknown> = Promise.resolve()

// Bounded, and never fails the hook: a daemon that is down or slow costs a badge,
// not the person's session. `held` marks a "waiting for you" the window keeps until
// this mod reports the next state, which for a question is the moment it is answered.
//
// Sent one after another, because a fetch cannot be abandoned: a report that outlived
// its hook's wait would otherwise land after the next one, and a late held "waiting"
// after the "working" that ended it stays on the rail. A report still unsent after
// several waits is given up on, so a hung daemon cannot hold back every later one.
async function report($: EngineInterface, state: string, held = false): Promise<void> {
  const send = sending
    .then(() =>
      Promise.race([
        $.http.fetch(`${DAEMON}/api/pty/sessions/${encodeURIComponent(session)}/agent-state`, {
          method: 'POST',
          headers: { 'content-type': 'application/json', 'x-veld-request': '1' },
          body: JSON.stringify(held ? { tool: 'claude', state, held } : { tool: 'claude', state }),
        }),
        $.clock.sleep(TIMEOUT_MS * 5),
      ]),
    )
    .catch(() => {})
  sending = send
  await Promise.race([send, $.clock.sleep(TIMEOUT_MS)]).catch(() => {})
}

// Take the session's outfit note from the daemon: its text, or nothing — where outfit
// has no profiles to offer, and on any failure. Bounded like a report.
async function askContext($: EngineInterface): Promise<string | undefined> {
  try {
    const res = await Promise.race([
      $.http.fetch(`${DAEMON}/api/pty/sessions/${encodeURIComponent(session)}/context`, {
        method: 'POST',
        headers: { 'x-veld-request': '1' },
      }),
      $.clock.sleep(TIMEOUT_MS).then(() => undefined),
    ])
    if (!res || !res.ok) return undefined
    const answer = JSON.parse(res.text).context
    return typeof answer === 'string' ? answer : undefined
  } catch {
    return undefined
  }
}

// Put one naming turn to the daemon and read its answer: `remind`, `block`, or nothing.
// Bounded like a report, and nothing on any failure.
async function askNaming($: EngineInterface, turn: object): Promise<string | undefined> {
  try {
    const res = await Promise.race([
      $.http.fetch(`${DAEMON}/api/pty/sessions/${encodeURIComponent(session)}/naming`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-veld-request': '1' },
        body: JSON.stringify(turn),
      }),
      $.clock.sleep(TIMEOUT_MS).then(() => undefined),
    ])
    if (!res || !res.ok) return undefined
    const answer = JSON.parse(res.text).naming
    return typeof answer === 'string' ? answer : undefined
  } catch {
    return undefined
  }
}
